    51  HB_UNUSED static inline unsigned int
    52  _plan_estimate_subset_table_size (hb_subset_plan_t *plan,
    53                                    unsigned int table_len);
    54  static inline unsigned int
    55  _plan_estimate_subset_table_size (hb_subset_plan_t *plan,
    56                                    unsigned int table_len)
    57  {
    58    unsigned int src_glyphs = plan->source->get_num_glyphs ();
    59    unsigned int dst_glyphs = plan->glyphset ()->get_population ();
    60
    61    if (unlikely (!src_glyphs))
    62      return 512 + table_len;
    63
    64    return 512 + (unsigned int) (table_len * sqrt ((double) dst_glyphs / src_glyphs));
    65  }
