   131  template<typename TableType>
   132  static bool
   133  _subset (hb_subset_plan_t *plan)
   134  {
   135    hb_blob_t *source_blob = hb_sanitize_context_t ().reference_table<TableType> (plan->source);
   136    const TableType *table = source_blob->as<TableType> ();
   137
   138    hb_tag_t tag = TableType::tableTag;
   139    hb_bool_t result = false;
   140    if (source_blob->data)
   141      result = table->subset (plan);
   142    else
   143      DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset sanitize failed on source table.", HB_UNTAG (tag));
   144
   145    hb_blob_destroy (source_blob);
   146    DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset %s", HB_UNTAG (tag), result ? "success" : "FAILED!");
   147    return result;
   148  }
