   151  static bool
   152  _subset_table (hb_subset_plan_t *plan,
   153                 hb_tag_t          tag)
   154  {
   155    DEBUG_MSG(SUBSET, nullptr, "begin subset %c%c%c%c", HB_UNTAG (tag));
   156    bool result = true;
   157    switch (tag) {
   158      case HB_OT_TAG_glyf:
   159        result = _subset<const OT::glyf> (plan);
   160        break;
   161      case HB_OT_TAG_hdmx:
   162        result = _subset<const OT::hdmx> (plan);
   163        break;
   164      case HB_OT_TAG_name:
   165        result = _subset2<const OT::name> (plan);
   166        break;
   167      case HB_OT_TAG_head:
   168        // TODO that won't work well if there is no glyf
   169        DEBUG_MSG(SUBSET, nullptr, "skip head, handled by glyf");
   170        result = true;
   171        break;
   172      case HB_OT_TAG_hhea:
   173        DEBUG_MSG(SUBSET, nullptr, "skip hhea handled by hmtx");
   174        return true;
   175      case HB_OT_TAG_hmtx:
   176        result = _subset<const OT::hmtx> (plan);
   177        break;
   178      case HB_OT_TAG_vhea:
   179        DEBUG_MSG(SUBSET, nullptr, "skip vhea handled by vmtx");
   180        return true;
   181      case HB_OT_TAG_vmtx:
   182        result = _subset<const OT::vmtx> (plan);
   183        break;
   184      case HB_OT_TAG_maxp:
   185        result = _subset<const OT::maxp> (plan);
   186        break;
   187      case HB_OT_TAG_loca:
   188        DEBUG_MSG(SUBSET, nullptr, "skip loca handled by glyf");
   189        return true;
   190      case HB_OT_TAG_cmap:
   191        result = _subset<const OT::cmap> (plan);
   192        break;
   193      case HB_OT_TAG_OS2:
   194        result = _subset<const OT::OS2> (plan);
   195        break;
   196      case HB_OT_TAG_post:
   197        result = _subset<const OT::post> (plan);
   198        break;
   199      case HB_OT_TAG_cff1:
   200        result = _subset<const OT::cff1> (plan);
